__NUXT_JSONP__("/finanzas-publicas/publicaciones/indice_de_fortaleza_fiscal_estatal", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{post:{slug:"indice_de_fortaleza_fiscal_estatal",title:i,date:"2025-04-07T15:52:32.571Z",img:"https:\u002F\u002Fucarecdn.com\u002Fbf86efd2-a829-4577-930c-81a0bb731c3a\u002F","img-alt":"índice de Fortaleza Fiscal Estatal",autor:"Ethos",category:e,extracto:"Con el objetivo de evaluar la fortaleza fiscal de los estados en México, Ethos desarrolló el **Índice de Fortaleza Fiscal Estatal**, el cual permite comparar el desempeño de las 32 entidades federativas en función de su generación de ingresos, gasto público y manejo de la deuda.",file:"https:\u002F\u002Fucarecdn.com\u002F1744a5cc-72d8-4dcd-b4ee-a97f06c29744\u002F",toc:[],body:{type:f,children:[{type:b,tag:c,props:{},children:[{type:a,value:"Con el objetivo de evaluar la fortaleza fiscal de los estados en México, Ethos desarrolló el "},{type:b,tag:"strong",props:{},children:[{type:a,value:i}]},{type:a,value:", el cual permite comparar el desempeño de las 32 entidades federativas en función de su generación de ingresos, gasto público y manejo de la deuda."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A partir de este análisis, buscamos aportar información clave para la toma de decisiones en materia de finanzas públicas estatales, fomentando una gestión más eficiente y sostenible que permita reducir la vulnerabilidad de los estados y  fortalecer su autonomía financiera en el largo plazo."}]}]},dir:g,path:"\u002Fpublicaciones\u002Findice_de_fortaleza_fiscal_estatal",extension:h,createdAt:"2025-04-23T06:21:15.398Z",updatedAt:"2025-04-23T06:21:15.399Z"},publicaciones:[{slug:"acelerando_la_fiscalidad_efectiva_al_tabaco_en_america_latina-_el_caso_de_mexico",title:"ACELERANDO LA FISCALIDAD EFECTIVA AL TABACO EN AMÉRICA LATINA. EL CASO DE MÉXICO",date:"2019-08-25T13:58:35.842Z",img:"https:\u002F\u002Fucarecdn.com\u002F4ecef13f-133d-46c0-879c-f8bd65f1eeda\u002F","img-alt":"Portada impuestos al tabaco",autor:"Liliana Alvarado, Dalia Toledo, Rodrigo Bolaños, Alejandro Alegría Matus, Claudia Cordova",category:e,extracto:j,file:"https:\u002F\u002Fucarecdn.com\u002Fd0a1a550-a3b4-4f74-a9ca-038c4ac33431\u002F",toc:[],body:{type:f,children:[{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:j}]},{type:a,value:d}]},dir:g,path:"\u002Fpublicaciones\u002Facelerando_la_fiscalidad_efectiva_al_tabaco_en_america_latina-_el_caso_de_mexico",extension:h,createdAt:"2023-06-19T05:12:04.224Z",updatedAt:"2022-08-28T22:41:58.244Z"},{slug:"analisis_del_paquete_economico_2026",title:"Análisis del Paquete Económico 2026",date:"2025-09-26T18:38:47.603Z",img:"https:\u002F\u002Fucarecdn.com\u002F89215cd3-b725-4493-8415-8a4c213d7dcc\u002F","img-alt":"Paquete económico 2026",autor:"Liliana Alvarado, Dalia Toledo y Mireya Mondragón",category:e,extracto:"El Paquete Económico 2026 es uno de los pilares sobre los cuales la presidenta Sheinbaum cimentará su proyecto de nación, y sin una reforma fiscal que permita aumentar los ingresos significativamente, ¿cuáles son las variables que se esperan que cambien para poder atender las necesidades de inversión, para garantizar bienes y servicios de calidad y hacer frente a los problemas que frenan el crecimiento económico y que impactan en el bienestar de la sociedad mexicana?",file:"https:\u002F\u002Fucarecdn.com\u002F977e0e4c-d871-496e-bcfe-b6917138e21e\u002F",toc:[],body:{type:f,children:[{type:b,tag:c,props:{},children:[{type:a,value:"En términos presupuestales, el primer año de la administración de la presidenta Claudia Sheinbum ha estado marcado por importantes recortes al gasto público y, aunque hay un fuerte interés por sanear las finanzas, las metas de endeudamiento no se están alcanzando. En ese sentido, este paquete es el segundo de los pilares sobre los cuales la presidenta Sheinbaum cimentará su proyecto de nación, y sin una reforma fiscal que permita aumentar los ingresos significativamente, ¿cuáles son las variables que se esperan que cambien para poder atender las necesidades de inversión, para garantizar bienes y servicios de calidad y hacer frente a los problemas que frenan el crecimiento económico y que impactan en el bienestar de la sociedad mexicana? Este documento intenta dar luz sobre estas preguntas."}]}]},dir:g,path:"\u002Fpublicaciones\u002Fanalisis_del_paquete_economico_2026",extension:h,createdAt:k,updatedAt:k},{slug:"analisis_del_paquete_fiscal_2010",title:"ANÁLISIS DEL PAQUETE FISCAL 2010",date:"2009-11-09T21:35:34.285Z",img:"https:\u002F\u002Fucarecdn.com\u002F3a044046-e93e-49f4-9df2-c1fc290cb776\u002F",autor:"Liliana Alvarado, Carlos Gaitán Lastras.",category:e,extracto:l,file:"https:\u002F\u002Fucarecdn.com\u002Fb0d5392f-78da-4c7c-a8a1-02b6b9e6bf91\u002F",toc:[],body:{type:f,children:[{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:l}]},{type:a,value:d}]},dir:g,path:"\u002Fpublicaciones\u002Fanalisis_del_paquete_fiscal_2010",extension:h,createdAt:"2023-06-19T05:12:04.231Z",updatedAt:"2022-08-24T22:31:42.859Z"}]}],fetch:{},mutations:[]}}("text","element","p","\n","finanzas-publicas","root","\u002Fpublicaciones",".md","Índice de Fortaleza Fiscal Estatal","Este estudio analiza las políticas de control del tabaco que se han implementado en México, enfocándose, en particular, en la efectividad que ha tenido la política tributaria para reducir el consumo de cigarrillos y en el impacto que el tabaquismo ha tenido sobre las finanzas públicas.","2025-11-25T01:24:03.286Z","Desafortunadamente, las modificaciones en materia fiscal no son de largo plazo, atienden sólo a las coyunturas económicas y políticas del momento")));